    const body=`<div class="login-brand"><img src="assets/see-you-logo.png" alt="See You"><div><span class="modal-eyebrow">SEE YOU / MEMBER SPACE</span><p>${escapeHTML(t('loginSubtitle'))}</p></div></div><form id="loginForm"><div class="field"><label for="loginEmail">${escapeHTML(t('emailOrPhone'))}</label><input type="email" id="loginEmail" required autocomplete="username" placeholder="client@seeyou.tn"></div><div class="field" style="margin-top:12px"><label for="loginPassword">${escapeHTML(t('password'))}</label><input type="password" id="loginPassword" required autocomplete="current-password" placeholder="••••••••"></div><p class="form-error hidden" id="loginError">${escapeHTML(t('loginError'))}</p><div class="form-actions"><button class="button button-gold" type="submit">${escapeHTML(t('login'))} ↗</button></div></form><div class="demo-credentials"><strong>${escapeHTML(t('demoAccounts'))}</strong><div class="credential-row"><span>${escapeHTML(t('adminDemo'))}</span><code tabindex="0" data-action="prefill-login" data-email="admin@seeyou.tn">admin@seeyou.tn</code></div><div class="credential-row"><span>${escapeHTML(t('password'))}</span><code>Admin123!</code></div><div class="credential-row"><span>${escapeHTML(t('clientDemo'))}</span><code tabindex="0" data-action="prefill-login" data-email="client@seeyou.tn">client@seeyou.tn</code></div><div class="credential-row"><span>${escapeHTML(t('password'))}</span><code>Client123!</code></div><p class="modal-note" style="margin:9px 0 0">${escapeHTML(t('loginDemoWarning'))}</p></div>`;
